from typing import List

class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        ans = 0
        n = len(nums)

        for i in range(n):
            for j in range(i, n):
                ok = True
                lst = -1

                for k in range(n):
                    if ok:
                        if i <= k < j:
                            ans += 1
                        elif lst < nums[k]:
                            lst = nums[k]
                        else:
                            ok = False

        return ans

